// Combine the scored lead with the AI-written email
const lead = $('Score Lead').item.json;
let subject = "", body = "";
try {
  const ai = JSON.parse($json.choices[0].message.content);
  subject = ai.subject; body = ai.body;
} catch (e) {
  subject = `Thanks for reaching out, ${lead.name.split(" ")[0]}`;
  body = "AI draft unavailable. Please write the first email manually.";
}
return { json: { ...lead, email_subject: subject, email_draft: body, status: "New" } };

